const e=["Dieu","Tentation","Religion","Force","Mystère"],t="Déesse de la Tentation",n=["Phiella représente la Tentation.","Elle n'incarne pas simplement le désir ou la séduction.","La tentation apparaît lorsqu'un choix difficile devient plus facile à accepter parce qu'une récompense se trouve de l'autre côté.","Pouvoir.","Richesse.","Amour.","Vengeance.","Connaissance.","Immortalité.","Tout peut devenir une tentation.","Phiella n'offre pas nécessairement ce que les mortels désirent.","Elle leur montre plutôt ce qu'ils seraient prêts à faire pour l'obtenir."],i=[{label:"Domaines",value:"Tentation"},{label:"Symboles",value:"Une pomme, une pièce d'or, une coupe, une clé, une main tendue, un masque"}],r=[{title:"Le désir",title_border:"#e8553d",type:"text",content:["Le désir n'est pas considéré comme mauvais dans le culte de Phiella.","Désirer quelque chose permet de comprendre ce qui compte réellement pour soi.","La tentation commence lorsque le désir devient suffisamment puissant pour faire oublier ses conséquences.","Un individu peut connaître les risques et choisir malgré tout.","C'est ce moment qui intéresse Phiella."]},{title:"Le prix",title_border:"#c2660a",type:"text",content:"Les traditions de Phiella insistent sur une idée simple :"},{title:"",type:"banner",content:"Toute tentation possède un prix.",subtitle:"À noter"},{title:"",type:"text",content:["Ce prix n'est pas nécessairement demandé par Phiella elle-même.","Il peut être moral, matériel ou émotionnel.","Un pouvoir obtenu trop facilement peut entraîner une dette.","Une vengeance peut coûter une relation.","Une richesse peut coûter une liberté.","Une connaissance peut coûter une part de son innocence.","Pour cette raison, les prêtres de Phiella enseignent rarement à leurs fidèles de résister à toute tentation.","Ils leur apprennent plutôt à regarder le prix avant de choisir."]},{title:"Phiella et les mortels",title_border:"#6f9fd8",type:"text",content:["Phiella est une divinité particulièrement présente dans les récits mettant en scène des mortels confrontés à leurs propres limites.","Elle peut être représentée comme une inconnue, une voix, une ombre ou simplement comme une présence.","Mais rien ne permet d'affirmer qu'elle intervient réellement dans ces histoires.","Beaucoup de récits qui lui sont attribués sont probablement des fables destinées à enseigner une morale.","D'autres sont beaucoup plus difficiles à expliquer."]},{title:"Le culte de Phiella",title_border:"#e8553d",type:"text",content:["Son culte est rarement organisé autour de grands temples.","On trouve plutôt de petits sanctuaires dans les lieux où les mortels sont confrontés à des choix importants :"]},{title:"",type:"list",content:["Marchés","Ports","Auberges","Quartiers riches","Lieux de jeux","Carrefours","Maisons de commerce"]},{title:"",type:"text",content:["Ses prêtres peuvent être conseillers, négociateurs, marchands ou simplement des personnes qui ont consacré leur vie à comprendre les désirs humains.","Certains cultes de Phiella sont secrets.","D'autres sont parfaitement légaux et ouvertement philosophiques."]},{title:"Phiella et Eone",title_border:"#c2660a",type:"text",content:["La relation entre Phiella et Eone est particulièrement intéressante.","La Connaissance peut elle-même devenir une tentation.","Un mortel qui découvre qu'une vérité dangereuse existe peut décider de continuer à chercher malgré les conséquences.","Pour cette raison, certains érudits considèrent Phiella comme une présence constante dans leurs recherches.","Ils ne la prient pas pour obtenir des réponses.","Ils la prient pour avoir le courage de décider s'ils doivent vraiment les connaître."]},{title:"Phiella et Neien",title_border:"#6f9fd8",type:"text",content:["La relation entre Phiella et Neien est également souvent évoquée.","La Vengeance peut devenir une tentation particulièrement puissante pour celui qui a subi une injustice.","Un désir légitime de réparation peut progressivement devenir le désir de faire souffrir quelqu'un.","Certains philosophes considèrent ainsi que l'histoire de Neien constitue l'un des exemples les plus importants de la manière dont une conviction peut devenir une tentation.","Cette interprétation reste cependant une lecture mortelle de son histoire."]},{title:"Symboles",title_border:"#e8553d",type:"text",content:"Phiella est généralement représentée par :"},{title:"",type:"list",content:["Une pomme","Une pièce d'or","Une coupe","Une clé","Une main tendue","Un masque"]},{title:"",type:"text",content:["La clé est particulièrement populaire.","Elle représente quelque chose qui pourrait être obtenu immédiatement, si seulement quelqu'un acceptait de tourner la serrure."]},{title:"Aujourd'hui",title_border:"#c2660a",type:"text",content:["Phiella est une divinité connue mais rarement vénérée publiquement.","Son nom apparaît dans les histoires de pactes, de trésors, de pouvoir et de choix impossibles.","Elle est parfois considérée comme une divinité dangereuse.","D'autres la voient simplement comme un miroir des désirs mortels.","Car la véritable question de Phiella n'est jamais :","« Que veux-tu ? »","Mais plutôt :","« Qu'es-tu prêt à perdre pour l'obtenir ? »"]}],s=["Les Dieux","Les Forces de la Conscience","Eone","Neien","La Tentation"],o={tags:e,surname:t,presentation:n,infos:i,sections:r,related:s};export{o as default,i as infos,n as presentation,s as related,r as sections,t as surname,e as tags};
